import { useId, useMemo, useRef, useState } from 'react'
import { product } from '../data/trailRunner2.js'

function Search() {
  const [query, setQuery] = useState('')
  const [open, setOpen] = useState(false)
  const [active, setActive] = useState(-1)
  const [chosen, setChosen] = useState('')
  const listId = useId()
  const inputRef = useRef(null)

  const matches = useMemo(() => {
    const q = query.trim().toLowerCase()
    if (!q) return []
    return product.searchProducts.filter((p) => p.toLowerCase().includes(q))
  }, [query])

  const expanded = open && matches.length > 0
  const optionId = (i) => `${listId}-opt-${i}`

  function choose(value) {
    setQuery(value)
    setChosen(value)
    setOpen(false)
    setActive(-1)
  }

  function onKeyDown(e) {
    if (e.key === 'ArrowDown') {
      e.preventDefault()
      if (!open) setOpen(true)
      setActive((a) => (matches.length ? (a + 1) % matches.length : -1))
    } else if (e.key === 'ArrowUp') {
      e.preventDefault()
      if (!open) setOpen(true)
      setActive((a) => (matches.length ? (a <= 0 ? matches.length - 1 : a - 1) : -1))
    } else if (e.key === 'Enter') {
      if (expanded && active >= 0) {
        e.preventDefault()
        choose(matches[active])
      }
    } else if (e.key === 'Escape') {
      if (expanded) {
        e.preventDefault()
        setOpen(false)
        setActive(-1)
      }
    }
  }

  return (
    <div className="search" role="search">
      <label htmlFor={`${listId}-input`} className="visually-hidden">Search products</label>
      <div className="combobox-wrap">
        <input
          id={`${listId}-input`}
          ref={inputRef}
          type="text"
          role="combobox"
          autoComplete="off"
          aria-autocomplete="list"
          aria-expanded={expanded}
          aria-controls={listId}
          aria-activedescendant={expanded && active >= 0 ? optionId(active) : undefined}
          value={query}
          onChange={(e) => {
            setQuery(e.target.value)
            setOpen(true)
            setActive(-1)
          }}
          onFocus={() => setOpen(true)}
          onBlur={() => setOpen(false)}
          onKeyDown={onKeyDown}
          placeholder="Search products"
        />
        <ul
          id={listId}
          role="listbox"
          aria-label="Product suggestions"
          hidden={!expanded}
          className="suggestions"
          onMouseDown={(e) => e.preventDefault()}
        >
          {matches.map((m, i) => (
            <li
              key={m}
              id={optionId(i)}
              role="option"
              aria-selected={i === active}
              className={i === active ? 'is-active' : undefined}
              onClick={() => choose(m)}
            >
              {m}
            </li>
          ))}
        </ul>
      </div>
      <p className="visually-hidden" aria-live="polite">
        {open && matches.length ? `${matches.length} suggestions` : ''}
        {chosen ? `Selected ${chosen}` : ''}
      </p>
    </div>
  )
}

function MenuItem({ section, onEscapeOut }) {
  const [expanded, setExpanded] = useState(false)
  const id = useId()
  return (
    <li className="menu-item">
      <button
        type="button"
        aria-expanded={expanded}
        aria-controls={id}
        onClick={() => setExpanded((v) => !v)}
        onKeyDown={(e) => {
          if (e.key === 'Escape' && expanded) {
            e.preventDefault()
            setExpanded(false)
          }
        }}
      >
        {section.label}
      </button>
      <ul id={id} className="submenu" hidden={!expanded}>
        {section.subsections.map((s) => (
          <li key={s}>
            <a href="#" onKeyDown={(e) => { if (e.key === 'Escape') onEscapeOut?.() }}>{s}</a>
          </li>
        ))}
      </ul>
    </li>
  )
}

export default function Header() {
  return (
    <header className="site-header">
      <div className="top-bar">
        <a className="store-name" href="/">{product.storeName}</a>
        <Search />
        <a className="cart-link" href="#cart" aria-label={`Cart, ${product.cartCount} items`}>
          Cart <span aria-hidden="true" className="badge">{product.cartCount}</span>
        </a>
      </div>
      <nav aria-label="Main">
        <ul className="main-menu">
          {product.mainSections.map((s) => (
            <MenuItem key={s.label} section={s} />
          ))}
        </ul>
      </nav>
    </header>
  )
}
