const INTERVAL_MS = 5000

export default function Gallery() {
  const photos = product.photos
  const [index, setIndex] = useState(0)
  const [paused, setPaused] = useState(false)

  useEffect(() => {
    if (paused) return undefined
    const timer = setInterval(() => setIndex((i) => (i + 1) % photos.length), INTERVAL_MS)
    return () => clearInterval(timer)
  }, [paused, photos.length])

  const next = () => setIndex((i) => (i + 1) % photos.length)
  const prev = () => setIndex((i) => (i - 1 + photos.length) % photos.length)

  return (
    <section className="gallery" aria-roledescription="carousel" aria-label="Product photos">
      <div className="gallery-stage" aria-live={paused ? 'polite' : 'off'}>
        <div
          className="gallery-slide"
          role="group"
          aria-roledescription="slide"
          aria-label={`${index + 1} of ${photos.length}`}
        >
          <img src={photos[index].src} alt={photos[index].alt} />
        </div>
      </div>
      <div className="gallery-controls">
        <button type="button" onClick={prev} aria-label="Previous photo">
          <span aria-hidden="true">←</span>
        </button>
        <button
          type="button"
          onClick={() => setPaused((p) => !p)}
          aria-pressed={paused}
