          {paused ? 'Play photos' : 'Pause photos'}
        </button>
        <button type="button" onClick={next} aria-label="Next photo">
          <span aria-hidden="true">→</span>
        </button>
        <span className="gallery-count" aria-hidden="true">{index + 1} / {photos.length}</span>
      </div>
    </section>
  )
}
