import { useEffect, useId, useRef, useState } from 'react'
import { product } from '../data/trailRunner2.js'

// Approximate Paris-point conversion: EU = (foot cm + 1.5) * 1.5, US men's = EU - 33.
function sizeFromFoot(cm, system) {
  const eu = (cm + 1.5) * 1.5
  const target = system === 'eu' ? eu : eu - 33
  let best = null
  for (const s of product.sizes) {
    const value = system === 'eu' ? s.eu : s.us
    if (best === null || Math.abs(value - target) < Math.abs(best.value - target)) {
      best = { label: s.label, value }
    }
  }
  return best
}

export default function SizeGuide({ onUseSize, onClose }) {
  const [foot, setFoot] = useState('')
  const [system, setSystem] = useState('us')
  const [result, setResult] = useState(null)
  const [error, setError] = useState('')
  const titleId = useId()
  const footId = useId()
  const errorId = useId()
  const dialogRef = useRef(null)
  const firstFieldRef = useRef(null)

  useEffect(() => {
    firstFieldRef.current?.focus()
  }, [])

  useEffect(() => {
    const node = dialogRef.current
    function trap(e) {
      if (e.key === 'Escape') {
        e.preventDefault()
        onClose()
        return
      }
      if (e.key !== 'Tab') return
      const focusable = node.querySelectorAll('button, input, select, [tabindex]:not([tabindex="-1"])')
      const list = [...focusable].filter((el) => !el.disabled)
      if (!list.length) return
      const first = list[0]
      const last = list[list.length - 1]
      if (e.shiftKey && document.activeElement === first) {
        e.preventDefault()
        last.focus()
      } else if (!e.shiftKey && document.activeElement === last) {
        e.preventDefault()
        first.focus()
      }
    }
    document.addEventListener('keydown', trap)
    return () => document.removeEventListener('keydown', trap)
  }, [onClose])

  function calculate(e) {
    e.preventDefault()
    const cm = Number.parseFloat(foot)
    if (!Number.isFinite(cm) || cm < 15 || cm > 35) {
      setResult(null)
      setError('Enter a foot length between 15 and 35 cm.')
      return
    }
    setError('')
    setResult(sizeFromFoot(cm, system))
  }

  return (
    <div className="modal-backdrop">
      <div
        ref={dialogRef}
        className="modal"
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
      >
        <h2 id={titleId}>Size guide: {product.name}</h2>
        <table className="size-chart">
          <caption className="visually-hidden">Size conversion chart</caption>
          <thead>
            <tr><th scope="col">US</th><th scope="col">EU</th></tr>
          </thead>
          <tbody>
            {product.sizes.map((s) => (
              <tr key={s.label}>
                <th scope="row">{s.us}</th>
                <td>{s.eu}</td>
              </tr>
            ))}
          </tbody>
        </table>

        <form onSubmit={calculate} className="foot-form" noValidate>
          <div className="field">
            <label htmlFor={footId}>Foot length (cm)</label>
            <input
              id={footId}
              ref={firstFieldRef}
              type="number"
              inputMode="decimal"
              step="0.1"
              min="15"
              max="35"
              value={foot}
              onChange={(e) => setFoot(e.target.value)}
              aria-invalid={error ? 'true' : undefined}
              aria-describedby={error ? errorId : undefined}
            />
          </div>
          <fieldset className="system-fieldset">
            <legend>Convert to</legend>
            <label><input type="radio" name={`${footId}-system`} value="us" checked={system === 'us'} onChange={() => setSystem('us')} /> US</label>
            <label><input type="radio" name={`${footId}-system`} value="eu" checked={system === 'eu'} onChange={() => setSystem('eu')} /> EU</label>
          </fieldset>
          <button type="submit">Get my size</button>
          {error && <p id={errorId} role="alert" className="field-error">{error}</p>}
        </form>

        <div aria-live="polite">
          {result && (
            <p>
              Your size is <strong>{system.toUpperCase()} {result.label}</strong>.{' '}
              <button type="button" onClick={() => onUseSize(result.label)}>Use this size</button>
            </p>
          )}
        </div>

        <button type="button" onClick={onClose} className="modal-close">Close size guide</button>
      </div>
    </div>
  )
}
