import { useId, useRef, useState } from 'react'
import { product } from '../data/trailRunner2.js'
import SizeGuide from './SizeGuide.jsx'

export default function SizePicker({ value, onChange, error }) {
  const [open, setOpen] = useState(false)
  const [active, setActive] = useState(0)
  const [guideOpen, setGuideOpen] = useState(false)
  const buttonRef = useRef(null)
  const listId = useId()
  const labelId = useId()
  const guideButtonRef = useRef(null)
  const sizes = product.sizes
  const current = sizes.find((s) => s.label === value)

  function openList() {
    const idx = sizes.findIndex((s) => s.label === value)
    setActive(idx >= 0 ? idx : 0)
    setOpen(true)
  }

  function closeList(returnFocus = true) {
    setOpen(false)
    if (returnFocus) buttonRef.current?.focus()
  }

  function pick(i) {
    if (sizes[i].soldOut) return
    onChange(sizes[i].label)
    closeList()
  }

  function onListKeyDown(e) {
    if (e.key === 'ArrowDown') {
      e.preventDefault()
      setActive((a) => Math.min(a + 1, sizes.length - 1))
    } else if (e.key === 'ArrowUp') {
      e.preventDefault()
      setActive((a) => Math.max(a - 1, 0))
    } else if (e.key === 'Home') {
      e.preventDefault()
      setActive(0)
    } else if (e.key === 'End') {
      e.preventDefault()
      setActive(sizes.length - 1)
    } else if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault()
      pick(active)
    } else if (e.key === 'Escape') {
      e.preventDefault()
      closeList()
    } else if (e.key === 'Tab') {
      closeList(false)
    }
  }

  return (
    <div className="size-picker">
      <div className="size-label-row">
        <span id={labelId} className="field-label">
          Size: <span className="selected-value">{current ? `US ${current.label}` : 'Select a size'}</span>
        </span>
        <button
          ref={guideButtonRef}
          type="button"
          className="link-button"
          onClick={() => setGuideOpen(true)}
        >
          Size guide
        </button>
      </div>

      {!open ? (
        <button
          ref={buttonRef}
          type="button"
          className={`size-trigger${error ? ' has-error' : ''}`}
          aria-haspopup="listbox"
          aria-expanded="false"
          aria-labelledby={`${labelId} ${labelId}-btn`}
          id={`${labelId}-btn`}
          onClick={openList}
        >
          {current ? `US ${current.label}` : 'Choose size'}
        </button>
      ) : (
        <>
          <ul
            id={listId}
            role="listbox"
            aria-labelledby={labelId}
            tabIndex={-1}
            ref={(el) => el?.focus()}
            aria-activedescendant={`${listId}-${active}`}
            className="size-list"
            onKeyDown={onListKeyDown}
            onBlur={(e) => { if (!e.currentTarget.contains(e.relatedTarget)) closeList(false) }}
          >
            {sizes.map((s, i) => (
              <li
                key={s.label}
                id={`${listId}-${i}`}
                role="option"
                aria-selected={s.label === value}
                aria-disabled={s.soldOut ? 'true' : undefined}
                className={[i === active ? 'is-active' : '', s.soldOut ? 'is-sold-out' : ''].join(' ').trim()}
                onMouseDown={(e) => e.preventDefault()}
                onClick={() => pick(i)}
              >
                US {s.label}{s.soldOut ? ' (sold out)' : ''}
              </li>
            ))}
          </ul>
        </>
      )}

      {error && <p className="field-error" role="alert">{error}</p>}

      {guideOpen && (
        <SizeGuide
          onUseSize={(label) => {
            onChange(label)
            setGuideOpen(false)
            guideButtonRef.current?.focus()
          }}
          onClose={() => {
            setGuideOpen(false)
            guideButtonRef.current?.focus()
          }}
        />
      )}
    </div>
  )
}
