import { useRef, useState } from 'react'
import { product } from '../data/trailRunner2.js'

// APG grid: rows = stores, columns = sizes. Roving tabindex, arrow keys move between cells.
export default function StoreAvailability({ size, pickup, onPick }) {
  const sizes = product.sizes
  const stores = product.stores
  const [focus, setFocus] = useState({ r: 0, c: 0 })
  const cellRefs = useRef({})

  function move(r, c) {
    const nr = Math.max(0, Math.min(stores.length - 1, r))
    const nc = Math.max(0, Math.min(sizes.length - 1, c))
    setFocus({ r: nr, c: nc })
    cellRefs.current[`${nr}-${nc}`]?.focus()
  }

  function onKeyDown(e, r, c) {
    const keys = {
      ArrowRight: () => move(r, c + 1),
      ArrowLeft: () => move(r, c - 1),
      ArrowDown: () => move(r + 1, c),
      ArrowUp: () => move(r - 1, c),
      Home: () => move(r, 0),
      End: () => move(r, sizes.length - 1),
    }
    if (keys[e.key]) {
      e.preventDefault()
      keys[e.key]()
    } else if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault()
      const store = stores[r]
      const s = sizes[c]
      if (store.stock[s.label] && !s.soldOut) onPick({ storeId: store.id, size: s.label })
    }
  }

  const pickedLabel = pickup
    ? `Pickup selected: ${stores.find((s) => s.id === pickup.storeId)?.name}, US ${pickup.size}`
    : 'No pickup store selected.'

  return (
    <section className="store-availability" aria-labelledby="store-avail-heading">
      <h2 id="store-avail-heading">Check store availability</h2>
      <p className="hint">Use arrow keys to move between stores and sizes. Press Enter or Space to choose a pickup option.</p>
      <div className="grid-scroll">
        <table role="grid" aria-labelledby="store-avail-heading" aria-describedby="store-avail-status">
          <thead>
            <tr role="row">
              <td role="gridcell" aria-hidden="true" />
              {sizes.map((s) => (
                <th key={s.label} scope="col" role="columnheader">US {s.label}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {stores.map((store, r) => (
              <tr key={store.id} role="row">
                <th scope="row" role="rowheader">{store.name}</th>
                {sizes.map((s, c) => {
                  const available = !s.soldOut && store.stock[s.label]
                  const isPicked = pickup?.storeId === store.id && pickup?.size === s.label
                  const label = `${store.name}, US ${s.label}, ${available ? 'available' : 'unavailable'}`
                  return (
                    <td
                      key={s.label}
                      role="gridcell"
                      tabIndex={focus.r === r && focus.c === c ? 0 : -1}
                      ref={(el) => { cellRefs.current[`${r}-${c}`] = el }}
                      aria-label={label}
                      aria-selected={isPicked}
                      aria-disabled={available ? undefined : 'true'}
                      className={`stock-cell${available ? ' is-available' : ' is-unavailable'}${isPicked ? ' is-picked' : ''}`}
                      onFocus={() => setFocus({ r, c })}
                      onKeyDown={(e) => onKeyDown(e, r, c)}
                      onClick={() => available && onPick({ storeId: store.id, size: s.label })}
                    >
                      <span aria-hidden="true">{available ? (isPicked ? '✓' : 'In stock') : '—'}</span>
                    </td>
                  )
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <p id="store-avail-status" aria-live="polite">{pickedLabel}</p>
      {size && <p className="hint">Your selected size is US {size}.</p>}
    </section>
  )
}
