import { useEffect, useId, useMemo, useRef, useState } from 'react'

const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']

function startOfDay(d) {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate())
}

// Demo rule: deliveries are available from tomorrow, except every 7th day of the month.
function isAvailable(date, minDate) {
  return date >= minDate && date.getDate() % 7 !== 0
}

function addDays(d, n) {
  return new Date(d.getFullYear(), d.getMonth(), d.getDate() + n)
}

function addMonths(d, n) {
  const target = new Date(d.getFullYear(), d.getMonth() + n, 1)
  const lastDay = new Date(target.getFullYear(), target.getMonth() + 1, 0).getDate()
  return new Date(target.getFullYear(), target.getMonth(), Math.min(d.getDate(), lastDay))
}

export default function DeliveryDate({ value, onChange }) {
  const today = useMemo(() => startOfDay(new Date()), [])
  const minDate = useMemo(() => addDays(today, 1), [today])
  const [open, setOpen] = useState(false)
  const [focused, setFocused] = useState(value ?? minDate)
  const dialogId = useId()
  const titleId = useId()
  const triggerRef = useRef(null)
  const gridRef = useRef(null)

  useEffect(() => {
    if (open) gridRef.current?.querySelector('[tabindex="0"]')?.focus()
  }, [open, focused])

  const monthStart = new Date(focused.getFullYear(), focused.getMonth(), 1)
  const firstWeekday = monthStart.getDay()
  const daysInMonth = new Date(focused.getFullYear(), focused.getMonth() + 1, 0).getDate()
  const cells = []
  for (let i = 0; i < firstWeekday; i++) cells.push(null)
  for (let d = 1; d <= daysInMonth; d++) cells.push(new Date(focused.getFullYear(), focused.getMonth(), d))

  function close(returnFocus = true) {
    setOpen(false)
    if (returnFocus) triggerRef.current?.focus()
  }

  function pick(date) {
    if (!isAvailable(date, minDate)) return
    onChange(date)
    close()
  }

  function onKeyDown(e) {
    const moves = {
      ArrowRight: () => addDays(focused, 1),
      ArrowLeft: () => addDays(focused, -1),
      ArrowDown: () => addDays(focused, 7),
      ArrowUp: () => addDays(focused, -7),
      PageDown: () => addMonths(focused, 1),
      PageUp: () => addMonths(focused, -1),
    }
    if (e.key === 'Escape') {
      e.preventDefault()
      close()
    } else if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault()
      pick(focused)
    } else if (e.key === 'Home') {
      e.preventDefault()
      setFocused(new Date(focused.getFullYear(), focused.getMonth(), 1))
    } else if (e.key === 'End') {
      e.preventDefault()
      setFocused(new Date(focused.getFullYear(), focused.getMonth(), daysInMonth))
    } else if (moves[e.key]) {
      e.preventDefault()
      setFocused(moves[e.key]())
    }
  }

  const label = value
    ? value.toLocaleDateString('en-CA', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })
    : 'None chosen'

  return (
    <div className="delivery">
      <div className="field-label">Delivery date: <span className="selected-value">{label}</span></div>
      <button
        ref={triggerRef}
        type="button"
        aria-haspopup="dialog"
        aria-expanded={open}
        aria-controls={open ? dialogId : undefined}
        onClick={() => { setFocused(value ?? minDate); setOpen((o) => !o) }}
      >
        {value ? 'Change delivery date' : 'Choose delivery date'}
      </button>

      {open && (
        <div id={dialogId} role="dialog" aria-modal="false" aria-labelledby={titleId} className="calendar-popup">
          <div className="calendar-header">
            <button type="button" aria-label="Previous month" onClick={() => setFocused(addMonths(focused, -1))}>‹</button>
            <h3 id={titleId} aria-live="polite">{MONTHS[focused.getMonth()]} {focused.getFullYear()}</h3>
            <button type="button" aria-label="Next month" onClick={() => setFocused(addMonths(focused, 1))}>›</button>
          </div>
          <table role="grid" aria-labelledby={titleId} ref={gridRef} onKeyDown={onKeyDown}>
            <thead>
              <tr>{WEEKDAYS.map((w) => <th key={w} scope="col" abbr={w}>{w}</th>)}</tr>
            </thead>
            <tbody>
              {Array.from({ length: cells.length / 7 }, (_, row) => (
                <tr key={row}>
                  {cells.slice(row * 7, row * 7 + 7).map((date, col) => {
                    if (!date) return <td key={col} />
                    const available = isAvailable(date, minDate)
                    const isFocused = date.getTime() === focused.getTime()
                    const isChosen = value && date.getTime() === startOfDay(value).getTime()
                    return (
                      <td key={col} role="gridcell" aria-selected={isChosen ? 'true' : undefined} aria-disabled={available ? undefined : 'true'}>
                        <button
                          type="button"
                          tabIndex={isFocused ? 0 : -1}
                          aria-label={`${date.toLocaleDateString('en-CA', { weekday: 'long', month: 'long', day: 'numeric' })}${available ? '' : ', unavailable'}`}
                          className={`day${available ? '' : ' is-unavailable'}${isChosen ? ' is-chosen' : ''}`}
                          onFocus={() => setFocused(date)}
                          onClick={() => pick(date)}
                          onKeyDown={onKeyDown}
                          disabled={!available}
                        >
                          {date.getDate()}
                        </button>
                      </td>
                    )
                  })}
                </tr>
              ))}
            </tbody>
          </table>
          <button type="button" onClick={() => close()} className="link-button">Close calendar</button>
        </div>
      )}
    </div>
  )
}
