import { useRef, useState } from 'react'
import { product } from '../data/trailRunner2.js'

// APG tabs pattern: details, reviews, shipping. Only the active panel is shown.
const TABS = [
  { id: 'details', label: 'Details' },
  { id: 'reviews', label: 'Reviews' },
  { id: 'shipping', label: 'Shipping & Returns' },
]

function TabPanelBody({ id }) {
  if (id === 'details') {
    return (
      <dl className="detail-list">
        {Object.entries(product.details).map(([k, v]) => (
          <div key={k}><dt>{k}</dt><dd>{v}</dd></div>
        ))}
      </dl>
    )
  }
  if (id === 'reviews') {
    return (
      <ul className="reviews">
        {product.reviews.map((r) => (
          <li key={r.author}>
            <p><strong>{r.author}</strong> — {r.rating} out of 5 stars</p>
            <p>{r.text}</p>
          </li>
        ))}
      </ul>
    )
  }
  return <p>{product.shipping}</p>
}

export default function InfoTabs() {
  const [selected, setSelected] = useState('details')
  const tabRefs = useRef({})

  function select(id, focus = true) {
    setSelected(id)
    if (focus) tabRefs.current[id]?.focus()
  }

  function onKeyDown(e, index) {
    let next = null
    if (e.key === 'ArrowRight') next = (index + 1) % TABS.length
    else if (e.key === 'ArrowLeft') next = (index - 1 + TABS.length) % TABS.length
    else if (e.key === 'Home') next = 0
    else if (e.key === 'End') next = TABS.length - 1
    if (next !== null) {
      e.preventDefault()
      select(TABS[next].id)
    }
  }

  return (
    <section className="info-tabs" aria-labelledby="info-heading">
      <h2 id="info-heading" className="visually-hidden">More information</h2>
      <div role="tablist" aria-label="Product information" className="tablist">
        {TABS.map((t, i) => (
          <button
            key={t.id}
            ref={(el) => { tabRefs.current[t.id] = el }}
            type="button"
            role="tab"
            id={`tab-${t.id}`}
            aria-selected={selected === t.id}
            aria-controls={`panel-${t.id}`}
            tabIndex={selected === t.id ? 0 : -1}
            onClick={() => select(t.id, false)}
            onKeyDown={(e) => onKeyDown(e, i)}
          >
            {t.label}
          </button>
        ))}
      </div>
      {TABS.map((t) => (
        <div
          key={t.id}
          role="tabpanel"
          id={`panel-${t.id}`}
          aria-labelledby={`tab-${t.id}`}
          hidden={selected !== t.id}
          tabIndex={0}
          className="tabpanel"
        >
          {selected === t.id && <TabPanelBody id={t.id} />}
        </div>
      ))}
    </section>
  )
}
