.cart-message { margin: 12px 0 0; font-weight: 600; color: #1b6b2d; min-height: 1.4em; }

/* Store availability grid */
.store-availability { background: var(--panel); border-radius: 8px; padding: 24px; margin-top: 32px; }
.store-availability h2 { margin-top: 0; font-size: 1.25rem; }
.hint { color: var(--muted); font-size: .95rem; }
.grid-scroll { overflow-x: auto; }
[role="grid"] { border-collapse: collapse; width: 100%; min-width: 480px; }
[role="grid"] th, [role="grid"] td { border: 1px solid var(--line); padding: 0; }
[role="grid"] th { padding: 10px; text-align: left; font-weight: 600; background: #fafbfc; }
.stock-cell {
  min-width: 80px; min-height: 44px; text-align: center; cursor: pointer;
  padding: 10px 6px !important;
}
.stock-cell:focus-visible { outline: 3px solid var(--focus); outline-offset: -3px; position: relative; z-index: 1; }
.stock-cell.is-available { color: #14532d; font-weight: 600; }
.stock-cell.is-unavailable { color: #6b6f75; background: #f1f2f4; cursor: not-allowed; }
.stock-cell.is-picked { background: #dff3e4; outline: 2px solid #14532d; outline-offset: -2px; }

/* Info tabs */
.info-tabs { margin-top: 32px; background: var(--panel); border-radius: 8px; padding: 0 24px 24px; }
.tablist { display: flex; flex-wrap: wrap; gap: 4px; border-bottom: 1px solid var(--line); }
.tablist button {
  min-height: 48px; padding: 12px 16px; border: 0; background: none; cursor: pointer; color: var(--muted);
  border-bottom: 3px solid transparent; font-weight: 600;
}
.tablist button[aria-selected="true"] { color: var(--ink); border-bottom-color: var(--accent); }
.tabpanel { padding: 16px 0; }
.detail-list div { margin-bottom: 12px; }
.detail-list dt { font-weight: 600; }
.detail-list dd { margin: 4px 0 0; }
.reviews { list-style: none; padding: 0; }
.reviews li { margin-bottom: 16px; }

/* FAQ */
.questions { margin-top: 32px; background: var(--panel); border-radius: 8px; padding: 24px; }
.questions h2 { margin-top: 0; font-size: 1.25rem; }
.accordion-item { border-top: 1px solid var(--line); }
.accordion-item h3 { margin: 0; font-size: 1rem; }
.accordion-item button {
  width: 100%; min-height: 48px; display: flex; justify-content: space-between; align-items: center;
  padding: 12px 0; background: none; border: 0; text-align: left; font-weight: 600; cursor: pointer;
}
.accordion-item [role="region"] p { margin: 0 0 12px; }

/* Footer */
.site-footer {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 24px;
  padding: 32px 24px; background: #e9ebee; border-top: 1px solid var(--line);
}
.site-footer h2 { font-size: 1rem; margin: 0 0 8px; }
.site-footer ul { list-style: none; padding: 0; margin: 0; }
.site-footer li a { display: inline-block; min-height: 32px; padding: 4px 0; color: var(--ink); }
.social { display: flex; flex-wrap: wrap; gap: 8px; }
.social a { min-height: 44px; display: inline-flex; align-items: center; padding: 0 8px; }

/* Modal */
.modal-backdrop { position: fixed; inset: 0; background: rgba(0,0,0,.5); display: flex; align-items: center; justify-content: center; padding: 16px; z-index: 50; }
.modal { background: var(--panel); border-radius: 8px; padding: 24px; max-width: 520px; width: 100%; max-height: 90vh; overflow: auto; }
.modal h2 { margin-top: 0; font-size: 1.25rem; }
.size-chart { border-collapse: collapse; margin-bottom: 16px; }
.size-chart th, .size-chart td { border: 1px solid var(--line); padding: 6px 14px; text-align: center; }
.foot-form { display: flex; flex-wrap: wrap; gap: 12px; align-items: flex-end; }
.foot-form .field input { min-height: 44px; padding: 8px; border: 1px solid #6b7078; border-radius: 6px; font: inherit; width: 140px; }
.foot-form .field label { display: block; font-weight: 600; margin-bottom: 4px; }
.system-fieldset label { display: inline-flex; align-items: center; gap: 6px; min-height: 44px; margin-right: 12px; }
.system-fieldset { margin: 0; }
.modal-close { margin-top: 16px; width: 100%; }
EOF
